         // Remove oldest trace this works because LinkedHashMap maintains insertion order
         String oldestTraceId = spansByTraceId.keySet().iterator().next();
         spansByTraceId.remove(oldestTraceId);
      }

      // Only notify listeners for root spans, so that we publish a single event per trace.
      if (isRootSpan(span)) {
         publishTraceEvent(traceId, span);
      }
   }

   /**
    * Determine whether the given span is a root span (i.e. it has no valid parent).
    *
    * @param span The span to inspect
    * @return true if the span is a root span, false otherwise
    */
   private boolean isRootSpan(ReadableSpan span) {
      SpanContext parentSpanContext = span.getParentSpanContext();
      return parentSpanContext == null || !parentSpanContext.isValid();
   }

   /**
    * Publish a TraceEvent for a freshly stored root span, extracting the service and operation names from the span
    * attributes (null when absent).
    */
   private void publishTraceEvent(String traceId, ReadableSpan span) {
      if (eventPublisher == null) {
         return;
      }
      Attributes attributes = span.toSpanData().getAttributes();
      String service = attributes.get(AttributeKey.stringKey("service.name"));
      String operation = attributes.get(AttributeKey.stringKey("operation.name"));
      eventPublisher.publishEvent(new TraceEvent(traceId, service, operation, null));
