package io.github.microcks.util.tracing;

import io.github.microcks.event.TraceEvent;

import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.api.common.Attributes;
import io.opentelemetry.sdk.trace.ReadableSpan;

import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Utility class providing helpers to filter and extract information from spans and trace events. Used by the live trace
 * streaming feature to decide which subscribers should receive which events.
 */
public final class SpanFilterUtil {

   private static final AttributeKey<String> SERVICE_NAME_KEY = AttributeKey.stringKey("service.name");
   private static final AttributeKey<String> OPERATION_NAME_KEY = AttributeKey.stringKey("operation.name");
   private static final AttributeKey<String> CLIENT_ADDRESS_KEY = AttributeKey.stringKey("client.address");

   /**
    * Private constructor to prevent instantiation of utility class.
    */
   private SpanFilterUtil() {
      throw new UnsupportedOperationException("Utility class cannot be instantiated");
   }

   /**
    * Match a value against a wildcard pattern.
    *
    * @param pattern The pattern to match against. {@code *} matches any non-null value; otherwise the value is matched
    *                as a full regular expression, falling back to exact string equality if the pattern is not a valid
    *                regex.
    * @param value   The value to test
    * @return true if the value matches the pattern
    */
   public static boolean matchesWildcard(String pattern, String value) {
      if (pattern == null && value == null) {
         return true;
      }
      if (pattern == null || value == null) {
         return false;
      }
      if ("*".equals(pattern)) {
         return true;
      }
      try {
         return Pattern.matches(pattern, value);
      } catch (PatternSyntaxException e) {
         // Not a valid regex, fall back to exact string equality.
         return pattern.equals(value);
      }
   }

   /**
    * Extract a TraceEvent from a list of spans belonging to a trace. The service, operation and client address are
    * extracted from the {@code service.name}, {@code operation.name} and {@code client.address} span attributes
    * respectively (null when absent).
    *
    * @param traceId The trace identifier
    * @param spans   The spans belonging to the trace
    * @return A TraceEvent holding the extracted values
    */
   public static TraceEvent extractTraceEvent(String traceId, List<ReadableSpan> spans) {
      String service = null;
      String operation = null;
      String clientAddress = null;

      if (spans != null) {
         for (ReadableSpan span : spans) {
            Attributes attributes = span.toSpanData().getAttributes();
            if (service == null) {
               service = attributes.get(SERVICE_NAME_KEY);
            }
            if (operation == null) {
               operation = attributes.get(OPERATION_NAME_KEY);
            }
            if (clientAddress == null) {
               clientAddress = attributes.get(CLIENT_ADDRESS_KEY);
            }
         }
      }

      return new TraceEvent(traceId, service, operation, clientAddress);
   }

   /**
    * Check whether a TraceEvent matches the given filter patterns for service, operation and client address.
    *
    * @param event         The event to test
    * @param service       The service pattern to match against the event's service
    * @param operation     The operation pattern to match against the event's operation
    * @param clientAddress The client address pattern to match against the event's client address
    * @return true if all three fields match their respective patterns
    */
   public static boolean matchesTraceEvent(TraceEvent event, String service, String operation, String clientAddress) {
      return matchesWildcard(service, event.service()) && matchesWildcard(operation, event.operation())
            && matchesWildcard(clientAddress, event.clientAddress());
   }
}
