import io.github.microcks.event.TraceEvent;
import io.github.microcks.service.SpanStorageService;
import io.github.microcks.util.tracing.SpanFilterUtil;

import io.opentelemetry.sdk.trace.ReadableSpan;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Manages client subscriptions for live streaming of trace events. Clients register an {@link SseEmitter} together with
 * filter criteria (service name, operation name and client address). Whenever new trace data arrives, matching
 * subscribers are notified through Server-Sent Events.
 */
@Component
public class TraceSubscriptionManager {

   private static final Logger log = LoggerFactory.getLogger(TraceSubscriptionManager.class);

   /** Name of the SSE event used to keep connections alive. */
   private static final String HEARTBEAT_EVENT_NAME = "heartbeat";

   /** Name of the SSE event used to deliver trace updates. */
   private static final String TRACE_EVENT_NAME = "trace";

   private final SpanStorageService spanStorageService;

   /** Thread-safe list of active subscriptions. */
   private final List<Subscription> subscriptions = new CopyOnWriteArrayList<>();

   /**
    * Create a new TraceSubscriptionManager.
    *
    * @param spanStorageService The service used to retrieve spans for a trace
    */
   public TraceSubscriptionManager(SpanStorageService spanStorageService) {
      this.spanStorageService = spanStorageService;
   }

   /**
    * Register an emitter for a filtered live stream of trace events. A heartbeat event is sent immediately to confirm
    * the subscription and to establish the SSE stream.
    *
    * @param emitter       The SSE emitter to register
    * @param serviceName   The service name filter (may be a wildcard or regex)
    * @param operationName The operation name filter (may be a wildcard or regex)
    * @param clientAddress The client address filter (may be a wildcard or regex)
    */
   public void subscribe(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
      Subscription subscription = new Subscription(emitter, serviceName, operationName, clientAddress);
      subscriptions.add(subscription);

      emitter.onCompletion(() -> subscriptions.remove(subscription));
      emitter.onTimeout(() -> {
         subscriptions.remove(subscription);
         emitter.complete();
      });
      emitter.onError(t -> subscriptions.remove(subscription));

      // Send an immediate heartbeat to confirm the subscription is established.
      sendHeartbeat(subscription);
   }

   /**
    * Handle a newly arrived {@link TraceEvent}. Retrieves the spans for the corresponding trace and notifies all
    * matching subscribers.
    *
    * @param event The trace event to process
    */
   @EventListener
   public void onTraceUpdated(TraceEvent event) {
      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(event.traceId());
      if (spans == null || spans.isEmpty()) {
         // Nothing to send if there is no trace data yet.
         return;
      }

      for (Subscription subscription : subscriptions) {
         if (SpanFilterUtil.matchesTraceEvent(event, subscription.serviceName(), subscription.operationName(),
               subscription.clientAddress())) {
            try {
               subscription.emitter().send(SseEmitter.event().name(TRACE_EVENT_NAME)
                     .data(Map.of("traceId", event.traceId())));
            } catch (IOException e) {
               log.debug("Failed to send trace event to subscriber, completing emitter: {}", e.getMessage());
               subscription.emitter().complete();
            }
         }
      }
   }

   /**
    * Send a heartbeat SSE event to all registered emitters. This keeps the SSE connections alive and lets clients
    * detect broken streams.
    */
   @Scheduled(fixedRate = 30000)
   public void sendHeartbeats() {
      for (Subscription subscription : subscriptions) {
         sendHeartbeat(subscription);
      }
   }

   /** Send a single heartbeat SSE event to the given subscription. */
   private void sendHeartbeat(Subscription subscription) {
      try {
         subscription.emitter().send(SseEmitter.event().name(HEARTBEAT_EVENT_NAME).data("ping"));
      } catch (IOException e) {
         log.debug("Failed to send heartbeat to subscriber, completing emitter: {}", e.getMessage());
         subscription.emitter().complete();
      }
   }

   /** Internal record representing a client subscription with its filter criteria. */
   record Subscription(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
   }
}
